css:
.section_systems{position:relative}
.ab_systems{position:relative;z-index:3;display:flex;flex-direction:column;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair)}
.ab_sys-list{display:contents}
.ab_sys{border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair)}
.ab_sys_h{display:grid;grid-template-columns:70px minmax(0,1fr) auto 40px;align-items:center;grid-row-gap:16px;grid-column-gap:16px;width:100%;padding-top:22px;padding-bottom:22px;cursor:pointer}
.ab_sys_ix{color:var(--_color---text--tertiary);font-size:13px}
.ab_sys_nm{font-weight:800;font-stretch:112%;font-size:clamp(20px,2.4vw,32px);line-height:1.05;text-transform:uppercase;transition:color 250ms ease,transform 350ms cubic-bezier(.2,.9,.2,1)}
.ab_sys_tg{color:var(--_color---text--tertiary);font-size:11px;letter-spacing:0.06em;text-transform:uppercase;white-space:nowrap}
.ab_sys_st{display:grid;align-items:center;justify-items:center;width:34px;height:34px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong);transition:transform 350ms ease,background-color 300ms ease,color 300ms ease,border-color 300ms ease}
.ab_sys_b{height:0;overflow-x:hidden;overflow-y:hidden}
.ab_sys_in{display:grid;grid-template-columns:70px minmax(0,6fr) minmax(0,5fr);grid-row-gap:16px;grid-column-gap:28px;padding-bottom:30px}
.ab_sys_lbl{margin-bottom:6px;color:var(--_color---text--tertiary);font-size:11px;letter-spacing:0.12em;text-transform:uppercase}
.ab_sys_lbl.is-why{color:var(--_color---brand--signal)}
.ab_sys_p{color:var(--_color---text--secondary);font-size:16px;line-height:1.6}
.ab_sys_why{margin-top:14px;padding-top:12px;padding-right:14px;padding-bottom:12px;padding-left:14px;border-top-width:1px;border-top-style:dashed;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:dashed;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:dashed;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:dashed;border-left-color:var(--_color---neutral--hair-strong);color:var(--_color---text--primary)}
.ab_sys_eng{font-size:13.5px;line-height:1.7;color:var(--_color---text--secondary)}
@media screen and (max-width: 767px) {
.ab_sys_h{grid-template-columns:40px minmax(0,1fr) 34px}
.ab_sys_tg{display:none}
.ab_sys_in{grid-template-columns:minmax(0,1fr)}
}
